/// Capacity of the gadget
#[derive(Clone,Debug,PartialEq)]
pub struct ComputeSigAdvCapacity{
	/// how many subsigs 
	pub subsigs: usize,

	/// how many sigs 
	pub sigs: usize,

	/// max_nibble_len, used to determine inp_step_queue_obj
	pub max_nibble_len: usize,

	/// basis_pats_in_trace (used to be compatibile for the
	/// step_queue_res). It determines the related lookup argument size. 
	pub basis_pats_in_trace: usize, 

	/// percentage of subsigs that are components of SubsigCounterConstraint
	/// e.g. (1|2|3)>4,2 requires that there are at least 5 matches
	/// of either 1,2,3 (some with multiple matches) and there are
	/// at least 2 distinct matches (e.g., 5 matches of just subsig 1 is not ok).
	/// Real data for linux binexec dataset: 
	/// max_subsigs (for discharging a file):  1026, max_ratio 16.666668
	/// avg_subsigs:  401.2398676592225 avg_ratio 7.11235321401159
	/// It's the max value needed for perc_comp_subsigs is 17 for binexec data set.
	pub perc_comp_subsigs: usize,
}

/// Advice for the Compute Sig Gadget.
#[derive(Clone,Debug)]
pub struct ComputeSigAdvAdvice<F:PrimeField>{
	/// the statement container object which is serialized to a vector
	/// of statement
	pub stmt_container: Rc<RefCell<Container<F>>>,

	/// capacity
	pub capacity: ComputeSigAdvCapacity,
}

#[allow(dead_code)]
/// This gadget is responsible for computing the discharged
/// SIGS from Subsigs. Note that this gadget should be ONLY included
/// in the last step of discharging a word for saving cost.
#[derive(Clone,Debug)]
pub struct ComputeSigAdvGadget<F:PrimeField>{ 
	/// the capacity
	pub capacity: ComputeSigAdvCapacity,

	// will be set when set_container_cfg is called
	pub cfgs_context: Option<Rc<Vec<ContainerConfig>>>,
	// dummy_cfg is used when cfgs_context is not ready yet
	pub dummy_cfg: ContainerConfig,
	pub my_idx_in_context: Option<usize>,
	_f: PhantomData<F>,
}

